import json,sqlite3
from playwright.sync_api import sync_playwright
from native_worker import R,W,native,now
D=sqlite3.connect(W/'jobs.sqlite');results=[]
script=r'''xml=>{document.body.innerHTML='<div id="g" style="width:8192px;height:8192px;position:relative"></div>';const g=new Graph(document.getElementById('g'));const doc=mxUtils.parseXml(xml);new mxCodec(doc).decode(doc.getElementsByTagName('mxGraphModel')[0],g.model);g.view.validate();const edges=Object.values(g.model.cells).filter(c=>c.edge),result=[];for(const edge of edges){const target=g.model.getTerminal(edge,false);if(!target)continue;const before=g.view.getState(edge);if(!before?.absolutePoints?.length)continue;const end=before.absolutePoints.at(-1).clone(),labels=(edge.children||[]).filter(c=>c.vertex),labelBefore=labels.map(c=>({id:c.id,x:g.view.getState(c)?.x,y:g.view.getState(c)?.y}));const geo=target.geometry.clone();g.model.beginUpdate();const moved=geo.clone();moved.x+=17;moved.y+=11;g.model.setGeometry(target,moved);g.model.endUpdate();g.view.validate();const after=g.view.getState(edge).absolutePoints.at(-1);result.push({edge:edge.id,target:target.id,endArrow:g.getCellStyle(edge).endArrow,endpoint_delta:{x:after.x-end.x,y:after.y-end.y},labels:labelBefore.map(b=>({id:b.id,before:b,after:{x:g.view.getState(g.model.cells[b.id])?.x,y:g.view.getState(g.model.cells[b.id])?.y},parent:g.model.cells[b.id].parent.id}))});g.model.beginUpdate();g.model.setGeometry(target,geo);g.model.endUpdate();g.view.validate();}g.destroy();return result;}'''
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/home/shaoshitong/.cache/ms-playwright/chromium-1228/chrome-linux64/chrome',args=['--disable-dev-shm-usage']);page=browser.new_page();page.route('**/*',lambda r:r.abort());page.set_content('<html></html>');page.evaluate('window.mxLoadResources=false;window.mxLoadStylesheets=false;window.onDrawioViewerLoad=()=>{}');page.add_script_tag(path=str(native.renderer_path(R).parent/'assets/viewer-static.min.js'))
 for item in json.loads((W/'code_svg_v3_pilot.json').read_text())['results']:
  if item['source']!='allenai--CoSyn-400K':continue
  id=item['id'];out=json.loads(D.execute('select output_record from jobs where id=?',(id,)).fetchone()[0]);moves=page.evaluate(script,(R/out['code_file']).read_text());ok=all(abs(x['endpoint_delta']['x']-17)<.05 and abs(x['endpoint_delta']['y']-11)<.05 and x['endArrow']!='none' for x in moves);results.append({'id':id,'moved_targets':len(moves),'ok':ok,'moves':moves});print(json.dumps({'id':id,'moved_targets':len(moves),'ok':ok}))
 browser.close()
(W/'graphviz_editability_audit.json').write_text(json.dumps({'checked_at_utc':now(),'results':results,'scope':'3 pilot cases; real graph model node move with native connector markers and edge-owned labels; not acceptance alone'},indent=2)+'\n')
assert all(r['ok'] for r in results)
